from typing import Any, Dict, List, Optional, Set, Tuple
import json
import os
import time


class Subsystem:
    """Provide subsystem behavior."""

    def __init__(self, journal_path: str, checkpoint_path: str):
        self.journal_path = journal_path
        self.checkpoint_path = checkpoint_path
        self.tasks = {}
        self.dependencies = {}

    def add_task(self, task_id: str, func: callable, dependencies: List[str], idempotency_key: Optional[str]=None):
        """Add task."""
        if task_id in self.tasks:
            raise ValueError(f'Task {task_id} already exists')
        self.tasks[task_id] = {'func': func, 'dependencies': set(dependencies), 'idempotency_key': idempotency_key, 'status': 'pending'}
        for dep in dependencies:
            if dep not in self.dependencies:
                self.dependencies[dep] = []
            self.dependencies[dep].append(task_id)

    def execute(self):
        """Execute."""
        while True:
            try:
                checkpoint = self.load_checkpoint()
                tasks_to_run = self.determine_tasks_to_run(checkpoint)
                for task_id in tasks_to_run:
                    self.run_task(task_id, checkpoint)
                self.save_checkpoint(checkpoint)
            except Exception as e:
                print(f'Error during execution: {e}')
                time.sleep(1)

    def determine_tasks_to_run(self, checkpoint: Dict[str, Any]) -> List[str]:
        """Determine tasks to run."""
        ready_tasks = []
        for task_id in self.tasks:
            if self.tasks[task_id]['status'] == 'pending':
                all_deps_met = True
                for dep in self.tasks[task_id]['dependencies']:
                    if dep not in checkpoint or checkpoint[dep] != self.tasks[dep]['idempotency_key']:
                        all_deps_met = False
                        break
                if all_deps_met:
                    ready_tasks.append(task_id)
        return ready_tasks

    def run_task(self, task_id: str, checkpoint: Dict[str, Any]):
        """Run task."""
        try:
            result = self.tasks[task_id]['func']()
            checkpoint[task_id] = self.tasks[task_id]['idempotency_key']
            print(f'Task {task_id} completed successfully')
        except Exception as e:
            print(f'Error running task {task_id}: {e}')
        finally:
            self.tasks[task_id]['status'] = 'completed'

    def load_checkpoint(self) -> Dict[str, Any]:
        """Load checkpoint."""
        if os.path.exists(self.checkpoint_path):
            with open(self.checkpoint_path, 'r') as f:
                return json.load(f)
        else:
            return {}

    def save_checkpoint(self, checkpoint: Dict[str, Any]):
        """Save checkpoint."""
        with open(self.checkpoint_path, 'w') as f:
            json.dump(checkpoint, f)


